    /// <summary>textwrap.wrap / textwrap.fill with their default options, ported from CPython's Lib/textwrap.py.</summary>
    internal static class PyTextWrap
    {
        const string Ws = @"[\t\n\x0b\x0c\r ]", Nws = @"[^\t\n\x0b\x0c\r ]", Wp = @"[\w!""'&.,?]", Lt = @"[^\d\W]";

        // TextWrapper.wordsep_re: whitespace, an em-dash between words, or a word (split after the hyphens of hyphenated words)
        static readonly Regex WordSep = new Regex(
            "(" + Ws + "+" +
            "|(?<=" + Wp + ")-{2,}(?=\\w)" +
            "|" + Nws + "+?(?:-(?:(?<=" + Lt + "{2}-)|(?<=" + Lt + "-" + Lt + "-))(?=" + Lt + "-?" + Lt + ")" +
            "|(?=" + Ws + "|\\z)" +
            "|(?<=" + Wp + ")(?=-{2,}\\w))" +
            ")", RegexOptions.CultureInvariant);

        public static List<string> Wrap(string text, int width, string initialIndent = "", string subsequentIndent = "")
        {
            var sb = new StringBuilder(text.Length);
            int col = 0;
            foreach (char c in text)
            {
                if (c == '\t') { int n = 8 - col % 8; sb.Append(' ', n); col += n; continue; }
                if (c == '\n' || c == '\r') col = 0; else col++;
                sb.Append(c == '\n' || c == '\x0b' || c == '\x0c' || c == '\r' ? ' ' : c);
            }
            var chunks = WordSep.Split(sb.ToString()).Where(c => c.Length > 0).ToList();
            return WrapChunks(chunks, width, initialIndent, subsequentIndent);
        }

        public static string Fill(string text, int width, string initialIndent = "", string subsequentIndent = "") =>
            string.Join("\n", Wrap(text, width, initialIndent, subsequentIndent));

        static bool Blank(string s) => s.Trim().Length == 0;

        static List<string> WrapChunks(List<string> chunks, int width, string initialIndent, string subsequentIndent)
        {
            var lines = new List<string>();
            if (width <= 0) throw new ArgumentException($"invalid width {width} (must be > 0)");
            chunks.Reverse();
            while (chunks.Count > 0)
            {
                var cur = new List<string>();
                int curLen = 0;
                string indent = lines.Count > 0 ? subsequentIndent : initialIndent;
                int w = width - indent.Length;
                if (Blank(chunks[^1]) && lines.Count > 0) chunks.RemoveAt(chunks.Count - 1);
                while (chunks.Count > 0)
                {
                    int l = chunks[^1].Length;
                    if (curLen + l > w) break;
                    cur.Add(chunks[^1]);
                    chunks.RemoveAt(chunks.Count - 1);
                    curLen += l;
                }
                if (chunks.Count > 0 && chunks[^1].Length > w)
                {
                    HandleLongWord(chunks, cur, curLen, w);
                    curLen = cur.Sum(c => c.Length);
                }
                if (cur.Count > 0 && Blank(cur[^1])) { curLen -= cur[^1].Length; cur.RemoveAt(cur.Count - 1); }
                if (cur.Count > 0) lines.Add(indent + string.Concat(cur));
            }
            return lines;
        }

        static void HandleLongWord(List<string> reversedChunks, List<string> cur, int curLen, int width)
        {
            int spaceLeft = width < 1 ? 1 : width - curLen;
            if (spaceLeft > 0)
            {
                int end = spaceLeft;
                string chunk = reversedChunks[^1];
                if (chunk.Length > spaceLeft)
                {
                    int hyphen = chunk.LastIndexOf('-', spaceLeft - 1, spaceLeft);
                    if (hyphen > 0 && chunk.Substring(0, hyphen).Any(c => c != '-')) end = hyphen + 1;
                }
                cur.Add(chunk.Substring(0, end));
                reversedChunks[^1] = chunk.Substring(end);
            }
            else if (cur.Count == 0)
            {
                cur.Add(reversedChunks[^1]);
                reversedChunks.RemoveAt(reversedChunks.Count - 1);
            }
        }
    }

    /// <summary>The console as CPython sees it: color support (_colorize.can_colorize) and the terminal width (shutil).</summary>
    internal static class PyConsole
    {
        static readonly Regex Ansi = new Regex("\x1b\\[[0-9;]*m", RegexOptions.CultureInvariant);

        public static string Decolor(string s) => s.IndexOf('\x1b') < 0 ? s : Ansi.Replace(s, "");

        /// <summary>_colorize.can_colorize(file=sys.stdout).</summary>
        public static bool CanColorize()
        {
            string? Env(string k) => Environment.GetEnvironmentVariable(k);
            if (Env("PYTHON_COLORS") == "0") return false;
            if (Env("PYTHON_COLORS") == "1") return true;
            if (!string.IsNullOrEmpty(Env("NO_COLOR"))) return false;
            if (!string.IsNullOrEmpty(Env("FORCE_COLOR"))) return true;
            if (Env("TERM") == "dumb") return false;
            try { return !Console.IsOutputRedirected; } catch (Exception) { return false; }
        }

        /// <summary>shutil.get_terminal_size().columns: $COLUMNS, else the width of the terminal on stdout, else 80.</summary>
        public static int TerminalColumns()
        {
            if (int.TryParse(Environment.GetEnvironmentVariable("COLUMNS"), out int c) && c > 0) return c;
            try { if (!Console.IsOutputRedirected && Console.WindowWidth > 0) return Console.WindowWidth; } catch (Exception) { }
            return 80;
        }

        /// <summary>file.write(text) on sys.stdout / sys.stderr, an open file, an io.StringIO, or any object with write().</summary>
        public static void Write(object? file, string text)
        {
            switch (file)
            {
                case null: Console.Error.Write(text); break;
                case PyTextStream ts: ts.write(text); break;
                case PyFile f: f.write(text); break;
                case StringIO sio: sio.write(text); break;
                case System.IO.TextWriter tw: tw.Write(text); break;
                default: ((dynamic)file).write(text); break;
            }
        }

        public static void Flush(object? file)
        {
            switch (file)
            {
                case null: Console.Error.Flush(); break;
                case PyTextStream ts: ts.flush(); break;
                case PyFile f: f.flush(); break;
                case StringIO: break;
                case System.IO.TextWriter tw: tw.Flush(); break;
                default: try { ((dynamic)file).flush(); } catch (Microsoft.CSharp.RuntimeBinder.RuntimeBinderException) { } break;
            }
        }

        /// <summary>Exits the process like sys.exit(status) (Typhon's sys.exit ends the process; it does not raise SystemExit).</summary>
        public static void Exit(int status)
        {
            try { Console.Out.Flush(); Console.Error.Flush(); } catch (Exception) { }
            Environment.Exit(status);
        }

        /// <summary>The name a Python callable would show as __name__ (the builtin or function a type= delegate calls).</summary>
        public static string? CallableName(Delegate? d)
        {
            if (d == null) return null;
            if (d.Target is PyFunction pf) return pf.__name__;
            var m = d.Method;
            if (!m.Name.Contains('<')) return m.Name;
            // a lambda the compiler made around a builtin or a function (type=int → __v => int(__v), type=f → __a0 => f(__a0)):
            // the method it calls; a lambda of the program's own is "<lambda>"
            try
            {
                var ps = m.GetParameters();
                string? last = ps.Length > 0 ? ps[^1].Name : null;
                if (last == null || !(last == "__v" || last.StartsWith("__a"))) return "<lambda>";
                var il = m.GetMethodBody()?.GetILAsByteArray();
                if (il == null) return null;
                for (int i = 0; i < il.Length;)
                {
                    byte op = il[i];
                    if (op == 0x00 || op >= 0x02 && op <= 0x05) { i++; continue; }              // nop, ldarg.0-3
                    if (op == 0x0E) { i += 2; continue; }                                        // ldarg.s
                    if (op == 0x28 || op == 0x6F)                                                // call, callvirt
                    {
                        int token = BitConverter.ToInt32(il, i + 1);
                        var callee = m.Module.ResolveMethod(token, m.DeclaringType?.GetGenericArguments(), m.GetGenericArguments());
                        string name = callee?.Name ?? "";
                        if (name == "__bigint") return "int";
                        return name.StartsWith("<") ? null : name;
                    }
                    return null;
                }
            }
            catch (Exception) { }
            return null;
        }
    }
