                var mv = MetavarTuple(argument.metavar)!;
                if (NargsIs(argument.nargs, ZERO_OR_MORE) && mv.Length == 2) return $"{mv[0]}[, {mv[1]}]";
                if (NargsIs(argument.nargs, ONE_OR_MORE)) return $"{mv[0]}[, {mv[1]}]";
                return string.Join(", ", mv);
