                AddArgument(new[] { a, b, c, d }, action, nargs, @const, @default, type, choices, required, help, metavar, dest, version, deprecated);

            public Action add_argument(params string[] names) =>
                AddArgument(names, null, null, null, null, null, null, null, null, null, null, null, false);

            Action AddArgument(string[] args, object? actionArg, object? nargs, object? @const, object? @default, Func<string, object?>? type,
                               object? choices, bool? required, string? help, object? metavar, string? dest, string? version, bool deprecated)
            {
                nargs = Norm(nargs); @const = Norm(@const); @default = Norm(@default);
                var a = new Action { nargs = nargs, @const = @const, type = type, choices = choices, help = help, metavar = metavar, version = version, deprecated = deprecated };
                bool defaultGiven = @default != null;
                if (args.Length == 0 || args.Length == 1 && (args[0].Length == 0 || prefix_chars.IndexOf(args[0][0]) < 0))
                {
                    // a positional argument
                    if (args.Length == 1 && dest != null) throw new InvalidCastException("dest supplied twice for positional argument, did you mean metavar?");
                    if (required != null) throw new InvalidCastException("'required' is an invalid argument for positionals");
                    if (nargs is long n0 && n0 == 0) throw new ArgumentException("nargs for positionals must be != 0");
                    a.dest = args.Length == 1 ? args[0] : dest ?? throw new InvalidCastException("missing dest");
                    a.required = !(NargsIs(nargs, OPTIONAL) || NargsIs(nargs, ZERO_OR_MORE) || NargsIs(nargs, REMAINDER) || IsSuppress(nargs));
                }
                else
                {
                    var longs = new List<string>();
                    foreach (var s in args)
                    {
                        if (s.Length == 0 || prefix_chars.IndexOf(s[0]) < 0)
                            throw new ArgumentException($"invalid option string {Builtins.repr(s)}: must start with a character {Builtins.repr(prefix_chars)}");
                        a.option_strings.Add(s);
                        if (s.Length > 1 && prefix_chars.IndexOf(s[1]) >= 0) longs.Add(s);
                    }
                    if (dest == null)
                    {
                        string from = longs.Count > 0 ? longs[0] : args[0];
                        dest = from.TrimStart(prefix_chars.ToCharArray());
                        if (dest.Length == 0) throw new InvalidCastException($"dest= is required for options like {Builtins.repr(args[^1])}");
                        dest = dest.Replace('-', '_');
                    }
                    a.dest = dest;
                    a.required = required ?? false;
                }
                if (!defaultGiven)
                {
                    if (Root._defaults.TryGetValue(a.dest, out var pd)) { @default = pd; defaultGiven = true; }
                    else if (argument_default != null) { @default = argument_default; defaultGiven = true; }
                }

                // the action class
                string kind;
                if (actionArg == null) kind = "store";
                else if (ReferenceEquals(actionArg, BooleanOptionalAction)) kind = "boolean_optional";
                else if (actionArg is string s && KnownActions.Contains(s)) kind = s;
                else throw new ArgumentException($"unknown action {Builtins.repr(actionArg)}");
                a.Kind = kind;
                CheckKeywords(kind, nargs, @const, defaultGiven, type, choices, metavar, version);
                switch (kind)
                {
                    case "store": case "append": case "extend":
                        if (nargs is long nz && nz == 0)
                            throw new ArgumentException(kind == "store"
                                ? "nargs for store actions must be != 0; if you have nothing to store, actions such as store true or store const may be more appropriate"
                                : "nargs for append actions must be != 0; if arg strings are not supplying the value to append, the append const action may be more appropriate");
                        if (@const != null && !NargsIs(nargs, OPTIONAL)) throw new ArgumentException("nargs must be '?' to supply const");
                        a.@default = @default;
                        break;
                    case "store_const": case "append_const":
                        a.nargs = 0L; a.@default = @default;
                        break;
                    case "store_true": a.nargs = 0L; a.@const = true; a.@default = defaultGiven ? @default : false; break;
                    case "store_false": a.nargs = 0L; a.@const = false; a.@default = defaultGiven ? @default : true; break;
                    case "count": a.nargs = 0L; a.@default = @default; break;
                    case "help":
                        a.nargs = 0L; a.@default = defaultGiven ? @default : SUPPRESS;
                        break;
                    case "version":
                        a.nargs = 0L; a.@default = defaultGiven ? @default : SUPPRESS;
                        a.help ??= "show program's version number and exit";
                        break;
                    case "boolean_optional":
                    {
                        var opts = new List<string>();
                        foreach (var o in a.option_strings)
                        {
                            opts.Add(o);
                            if (o.StartsWith("--"))
                            {
                                if (o.StartsWith("--no-")) throw new ArgumentException($"invalid option name {Builtins.repr(o)} for BooleanOptionalAction");
                                opts.Add("--no-" + o.Substring(2));
                            }
                        }
                        a.option_strings = opts; a.nargs = 0L; a.@default = @default;
                        break;
                    }
                    case "parsers": throw new ArgumentException("use add_subparsers() to add subcommands");
                }
                if (a.option_strings.Count == 0 && a.nargs is long nn && nn == 0)
                    throw new ArgumentException($"action {Builtins.repr(actionArg)} is not valid for positional arguments");
                // the metavar must fit nargs, and the help string must expand
                try { Root.ValidationFormatter()._format_args(a, null); }
                catch (InvalidCastException) { throw new ArgumentException("length of metavar tuple does not match nargs"); }
                Root.CheckHelp(a);
                return _add_action(a);
            }

            static void CheckKeywords(string kind, object? nargs, object? @const, bool defaultGiven, object? type, object? choices, object? metavar, string? version)
            {
                var allowed = ActionKeywords[kind];
                void Check(string name, bool given)
                {
                    if (given && Array.IndexOf(allowed, name) < 0)
                    {
                        string cls = kind switch
                        {
                            "store_const" => "_StoreConstAction", "append_const" => "_AppendConstAction", "store_true" => "_StoreTrueAction",
                            "store_false" => "_StoreFalseAction", "count" => "_CountAction", "help" => "_HelpAction", "version" => "_VersionAction",
                            "boolean_optional" => "BooleanOptionalAction", "append" => "_AppendAction", "extend" => "_ExtendAction", _ => "_StoreAction",
                        };
                        throw new InvalidCastException($"{cls}.__init__() got an unexpected keyword argument '{name}'");
                    }
                }
                Check("nargs", nargs != null); Check("const", @const != null); Check("type", type != null);
                Check("choices", choices != null); Check("metavar", metavar != null); Check("version", version != null);
            }

            internal virtual Action _add_action(Action action)
            {
                Root.CheckConflict(action);
                Root._actions.Add(action);
                action.container = this;
                foreach (var s in action.option_strings) Root._option_string_actions[s] = action;
                foreach (var s in action.option_strings)
                    if (NegativeNumber.IsMatch(s)) Root._has_negative_number_optionals = true;
                return action;
            }

            internal virtual void _remove_action(Action action) => Root._actions.Remove(action);

            public _ArgumentGroup add_argument_group(string? title = null, string? description = null)
            {
                if (this is _ArgumentGroup) throw new ArgumentException("argument groups cannot be nested");
                var group = new _ArgumentGroup(Root, title, description);
                Root._action_groups.Add(group);
                return group;
            }

            public _MutuallyExclusiveGroup add_mutually_exclusive_group(KwOnly _ = default, bool required = false)
            {
                if (this is _MutuallyExclusiveGroup) throw new ArgumentException("mutually exclusive groups cannot be nested");
                var group = new _MutuallyExclusiveGroup(Root, this, required);
                Root._mutually_exclusive_groups.Add(group);
                return group;
            }

            public object? get_default(string dest)
            {
                foreach (var a in Root._actions) if (a.dest == dest && a.@default != null) return a.@default;
                return Root._defaults.TryGetValue(dest, out var v) ? v : null;
            }
        }

        internal static readonly Regex NegativeNumber = new Regex(@"\A-\.?\d", RegexOptions.CultureInvariant);

        internal class _ArgumentGroup : _ActionsContainer
        {
            public readonly string? title;
            internal readonly List<Action> _group_actions = new List<Action>();

            internal _ArgumentGroup(ArgumentParser root, string? title, string? description)
                : base(root, description, root.prefix_chars, root.argument_default, root.conflict_handler) { this.title = title; }

            internal override Action _add_action(Action action)
            {
                base._add_action(action);
                _group_actions.Add(action);
                return action;
            }

            internal override void _remove_action(Action action) { base._remove_action(action); _group_actions.Remove(action); }
        }

        internal sealed class _MutuallyExclusiveGroup : _ArgumentGroup
        {
            public readonly bool required;
            internal readonly _ActionsContainer _container;

            internal _MutuallyExclusiveGroup(ArgumentParser root, _ActionsContainer container, bool required) : base(root, null, null)
            {
                this.required = required;
                _container = container;
            }

            internal override Action _add_action(Action action)
            {
                if (action.required) throw new ArgumentException("mutually exclusive arguments must be optional");
                _container._add_action(action);
                _group_actions.Add(action);
                return action;
            }

            internal override void _remove_action(Action action) { _container._remove_action(action); _group_actions.Remove(action); }
        }

        /// <summary>argparse.ArgumentParser.</summary>
        internal sealed class ArgumentParser : _ActionsContainer, IPyRepr
        {
            public string prog;
            public string? usage;
            public string? epilog;
            internal readonly int FormatterKind;
            internal readonly _Class FormatterType;
            public readonly string? fromfile_prefix_chars;
            public readonly bool add_help, allow_abbrev, exit_on_error, suggest_on_error, color;

            internal readonly List<Action> _actions = new List<Action>();
            internal readonly Dictionary<string, Action> _option_string_actions = new Dictionary<string, Action>();
            internal readonly List<_ArgumentGroup> _action_groups = new List<_ArgumentGroup>();
            internal readonly List<_MutuallyExclusiveGroup> _mutually_exclusive_groups = new List<_MutuallyExclusiveGroup>();
            internal readonly OrderedDictionary<string, object?> _defaults = new OrderedDictionary<string, object?>();
            internal bool _has_negative_number_optionals;
            internal readonly _ArgumentGroup _positionals, _optionals;
            Action? _subparsers;
            _Formatter? _validationFormatter;

            public ArgumentParser(string? prog = null, string? usage = null, string? description = null, string? epilog = null, IEnumerable? parents = null,
                                  object? formatter_class = null, string prefix_chars = "-", string? fromfile_prefix_chars = null, object? argument_default = null,
                                  string conflict_handler = "error", bool add_help = true, bool allow_abbrev = true, bool exit_on_error = true,
                                  KwOnly _ = default, bool suggest_on_error = false, bool color = true)
                : base(null, description, prefix_chars, Norm(argument_default), conflict_handler)
            {
                this.prog = prog ?? DefaultProg();
                this.usage = usage;
                this.epilog = epilog;
                FormatterType = formatter_class as _Class is { Kind: >= 0 } fc ? fc : HelpFormatter;
                FormatterKind = FormatterType.Kind;
                this.fromfile_prefix_chars = fromfile_prefix_chars;
                this.add_help = add_help;
                this.allow_abbrev = allow_abbrev;
                this.exit_on_error = exit_on_error;
                this.suggest_on_error = suggest_on_error;
                this.color = color;
                _positionals = add_argument_group("positional arguments");
                _optionals = add_argument_group("options");
                string defaultPrefix = prefix_chars.Contains('-') ? "-" : prefix_chars[0].ToString();
                if (add_help)
                    add_argument(defaultPrefix + "h", defaultPrefix + defaultPrefix + "help", action: "help", @default: SUPPRESS, help: "show this help message and exit");
                if (parents != null)
                    foreach (var p in parents)
                    {
                        if (!(p is ArgumentParser parent)) throw new InvalidCastException("parents must be a list of ArgumentParser");
                        AddContainerActions(parent);
                        foreach (var kv in parent._defaults) _defaults[kv.Key] = kv.Value;
                    }
            }

            static string DefaultProg()
            {
                string arg0 = sys_.argv.Count > 0 ? sys_.argv[0] : "";
                int slash = arg0.LastIndexOf('/');
                if (System.IO.Path.DirectorySeparatorChar == '\\') slash = Math.Max(slash, arg0.LastIndexOf('\\'));
                return arg0.Substring(slash + 1);
            }

            public string __repr__() =>
                $"ArgumentParser(prog={Builtins.repr(prog)}, usage={Builtins.repr(usage)}, description={Builtins.repr(description)}, " +
                $"formatter_class={FormatterType.__repr__()}, conflict_handler={Builtins.repr(conflict_handler)}, add_help={Builtins.repr(add_help)})";
            public override string ToString() => __repr__();

            internal override Action _add_action(Action action)
            {
                if (action.option_strings.Count > 0) _optionals._add_action(action);
                else _positionals._add_action(action);
                return action;
            }

            void AddContainerActions(ArgumentParser container)
            {
                var titleGroupMap = new Dictionary<string, _ArgumentGroup>();
                foreach (var g in _action_groups)
                {
                    if (titleGroupMap.ContainsKey(g.title ?? "")) throw new ArgumentException($"cannot merge actions - two groups are named {Builtins.repr(g.title)}");
                    titleGroupMap[g.title ?? ""] = g;
                }
                var groupMap = new Dictionary<Action, _ActionsContainer>();
                foreach (var g in container._action_groups)
                {
                    if (!titleGroupMap.ContainsKey(g.title ?? "")) titleGroupMap[g.title ?? ""] = add_argument_group(g.title, g.description);
                    foreach (var a in g._group_actions) groupMap[a] = titleGroupMap[g.title ?? ""];
                }
                foreach (var g in container._mutually_exclusive_groups)
                {
                    _ActionsContainer cont = g._container == container ? this : titleGroupMap[(g._container as _ArgumentGroup)?.title ?? ""];
                    var mutex = cont.add_mutually_exclusive_group(required: g.required);
                    foreach (var a in g._group_actions) groupMap[a] = mutex;
                }
                foreach (var a in container._actions) (groupMap.TryGetValue(a, out var c) ? c : this)._add_action(a);
            }

            internal void CheckConflict(Action action)
            {
                var conflicts = new List<(string, Action)>();
                foreach (var s in action.option_strings)
                    if (_option_string_actions.TryGetValue(s, out var other)) conflicts.Add((s, other));
                if (conflicts.Count == 0) return;
                if (conflict_handler == "resolve")
                {
                    foreach (var (s, other) in conflicts)
                    {
                        other.option_strings.Remove(s);
                        _option_string_actions.Remove(s);
                        if (other.option_strings.Count == 0) other.container?._remove_action(other);
                    }
                    return;
                }
                string msg = (conflicts.Count == 1 ? "conflicting option string: " : "conflicting option strings: ") + string.Join(", ", conflicts.Select(c => c.Item1));
                throw new ArgumentError(action, msg);
            }

            internal void CheckHelp(Action action)
            {
                if (string.IsNullOrEmpty(action.help)) return;
                try { ValidationFormatter()._expand_help(action); }
                catch (Exception e) when (e is ArgumentException || e is InvalidCastException || e is KeyNotFoundException || e is FormatException)
                { throw new ArgumentException("badly formed help string"); }
            }

            internal _Formatter ValidationFormatter() => _validationFormatter ??= GetFormatter();

            internal _Formatter GetFormatter() => new _Formatter(prog, FormatterKind, color && PyConsole.CanColorize());

            // ── subparsers ──

            /// <summary>add_subparsers(): the action whose add_parser() creates one parser per subcommand.</summary>
            public Action add_subparsers(KwOnly _ = default, string? title = null, string? description = null, string? prog = null, string? dest = null,
                                         bool required = false, string? help = null, string? metavar = null, object? action = null)
            {
                if (_subparsers != null) error("cannot have multiple subparser arguments");
                _ArgumentGroup group = title != null || description != null ? add_argument_group(title ?? "subcommands", description) : _positionals;
                if (prog == null)
                {
                    var f = new _Formatter(this.prog, FormatterKind, false);
                    f.add_usage(null, _actions.Where(a => a.option_strings.Count == 0).ToList(), _mutually_exclusive_groups, "");
                    prog = f.format_help().Trim();
                }
                var a = new Action
                {
                    Kind = "parsers", dest = dest ?? SUPPRESS, nargs = PARSER, required = required, help = help, metavar = metavar,
                    NameParserMap = new OrderedDictionary<string, ArgumentParser>(), ProgPrefix = prog, Color = color,
                };
                a.choices = a.NameParserMap;
                CheckHelp(a);
                group._add_action(a);
                _subparsers = a;
                return a;
            }

            // ── parsing ──

            public dynamic parse_args(IEnumerable? args = null, Namespace? @namespace = null)
            {
                var (ns, argv) = ParseKnownArgs(args, @namespace, false);
                if (argv.Count > 0)
                {
                    string msg = "unrecognized arguments: " + string.Join(" ", argv);
                    if (exit_on_error) error(msg);
                    throw new ArgumentError(null, msg);
                }
                return ns;
            }

            public (dynamic, List<string>) parse_known_args(IEnumerable? args = null, Namespace? @namespace = null)
            {
                var (ns, extras) = ParseKnownArgs(args, @namespace, false);
                return (ns, extras);
            }

            public dynamic parse_intermixed_args(IEnumerable? args = null, Namespace? @namespace = null)
            {
                var (ns, argv) = parse_known_intermixed_args(args, @namespace);
                if (argv.Count > 0)
                {
                    string msg = "unrecognized arguments: " + string.Join(" ", argv);
                    if (exit_on_error) error(msg);
                    throw new ArgumentError(null, msg);
                }
                return ns;
            }

            public (dynamic, List<string>) parse_known_intermixed_args(IEnumerable? args = null, Namespace? @namespace = null)
            {
                var bad = _actions.FirstOrDefault(a => a.option_strings.Count == 0 && (NargsIs(a.nargs, PARSER) || NargsIs(a.nargs, REMAINDER)));
                if (bad != null) throw new InvalidCastException($"parse_intermixed_args: positional arg with nargs={bad.nargs}");
                var (ns, extras) = ParseKnownArgs(args, @namespace, true);
                return (ns, extras);
            }

            (Namespace, List<string>) ParseKnownArgs(IEnumerable? args, Namespace? ns, bool intermixed)
            {
                var argList = args == null ? sys_.argv.Skip(1).ToList() : args.Cast<object?>().Select(a => a as string ?? Builtins.str(a)).ToList();
                ns ??= new Namespace();
                foreach (var action in _actions)
                    if (action.dest != SUPPRESS && !ns.Has(action.dest) && !IsSuppress(action.@default))
                        ns.Set(action.dest, action.@default);
                foreach (var kv in _defaults)
                    if (!ns.Has(kv.Key)) ns.Set(kv.Key, kv.Value);
                List<string> extras;
                if (exit_on_error)
                {
                    try { (ns, extras) = ParseKnownArgsCore(argList, ns, intermixed); }
                    catch (ArgumentError err) { error(err.Message); throw; }
                }
                else (ns, extras) = ParseKnownArgsCore(argList, ns, intermixed);
                if (ns.Has(UnrecognizedArgsAttr))
                {
                    if (ns.Get(UnrecognizedArgsAttr) is IEnumerable<string> more) extras.AddRange(more);
                    ns.Delete(UnrecognizedArgsAttr);
                }
                return (ns, extras);
            }

            readonly struct OptionTuple
            {
                public readonly Action? Action; public readonly string OptionString; public readonly string? Sep; public readonly string? ExplicitArg;
                public OptionTuple(Action? action, string optionString, string? sep, string? explicitArg) { Action = action; OptionString = optionString; Sep = sep; ExplicitArg = explicitArg; }
            }

            (Namespace, List<string>) ParseKnownArgsCore(List<string> argStrings, Namespace ns, bool intermixed)
            {
                if (fromfile_prefix_chars != null) argStrings = ReadArgsFromFiles(argStrings);

                // the actions each mutually exclusive argument cannot occur with
                var actionConflicts = new Dictionary<Action, List<Action>>();
                foreach (var g in _mutually_exclusive_groups)
                    for (int i = 0; i < g._group_actions.Count; i++)
                    {
                        if (!actionConflicts.TryGetValue(g._group_actions[i], out var list)) actionConflicts[g._group_actions[i]] = list = new List<Action>();
                        list.AddRange(g._group_actions.Take(i));
                        list.AddRange(g._group_actions.Skip(i + 1));
                    }

                // 'O' for an option, 'A' for an argument, '-' for '--'
                var optionStringIndices = new Dictionary<int, List<OptionTuple>>();
                var pattern = new StringBuilder();
                for (int i = 0; i < argStrings.Count; i++)
                {
                    if (argStrings[i] == "--")
                    {
                        pattern.Append('-');
                        for (i++; i < argStrings.Count; i++) pattern.Append('A');
                        break;
                    }
                    var tuples = ParseOptional(argStrings[i]);
                    if (tuples == null) pattern.Append('A');
                    else { optionStringIndices[i] = tuples; pattern.Append('O'); }
                }
                string argStringsPattern = pattern.ToString();

                var seenActions = new HashSet<Action>();
                var seenNonDefaultActions = new HashSet<Action>();
                var warned = new HashSet<string>();
                var extras = new List<string>();
                var extrasPattern = new List<char>();

                void TakeAction(Action action, List<string> argumentStrings, string? optionString = null)
                {
                    seenActions.Add(action);
                    object? argumentValues = GetValues(action, argumentStrings);
                    if (action.option_strings.Count > 0 || argumentStrings.Count > 0)
                    {
                        seenNonDefaultActions.Add(action);
                        if (actionConflicts.TryGetValue(action, out var conflicts))
                            foreach (var c in conflicts)
                                if (seenNonDefaultActions.Contains(c)) throw new ArgumentError(action, "not allowed with argument " + NameOf(c));
                    }
                    if (!ReferenceEquals(argumentValues, SUPPRESS)) Invoke(action, ns, argumentValues, optionString);
                }

                int ConsumeOptional(int startIndex)
                {
                    var optionTuples = optionStringIndices[startIndex];
                    if (optionTuples.Count > 1)
                    {
                        string options = string.Join(", ", optionTuples.Select(t => t.OptionString));
                        throw new ArgumentError(null, $"ambiguous option: {argStrings[startIndex]} could match {options}");
                    }
                    var (action, optionString, sep, explicitArg) = (optionTuples[0].Action, optionTuples[0].OptionString, optionTuples[0].Sep, optionTuples[0].ExplicitArg);
                    var actionTuples = new List<(Action, List<string>, string)>();
                    int stop;
                    while (true)
                    {
                        if (action == null)
                        {
                            extras.Add(argStrings[startIndex]);
                            extrasPattern.Add('O');
                            return startIndex + 1;
                        }
                        if (explicitArg != null)
                        {
                            int argCount = MatchArgument(action, "A");
                            if (argCount == 0 && prefix_chars.IndexOf(optionString[1]) < 0 && explicitArg != "")
                            {
                                if (!string.IsNullOrEmpty(sep) || prefix_chars.IndexOf(explicitArg[0]) >= 0)
                                    throw new ArgumentError(action, "ignored explicit argument " + Builtins.repr(explicitArg));
                                actionTuples.Add((action, new List<string>(), optionString));
                                char ch = optionString[0];
                                optionString = ch.ToString() + explicitArg[0];
                                if (_option_string_actions.TryGetValue(optionString, out var next))
                                {
                                    action = next;
                                    explicitArg = explicitArg.Substring(1);
                                    if (explicitArg.Length == 0) sep = explicitArg = null;
                                    else if (explicitArg[0] == '=') { sep = "="; explicitArg = explicitArg.Substring(1); }
                                    else sep = "";
                                }
                                else
                                {
                                    extras.Add(ch + explicitArg);
                                    extrasPattern.Add('O');
                                    stop = startIndex + 1;
                                    break;
                                }
                            }
                            else if (argCount == 1)
                            {
                                stop = startIndex + 1;
                                actionTuples.Add((action, new List<string> { explicitArg }, optionString));
                                break;
                            }
                            else throw new ArgumentError(action, "ignored explicit argument " + Builtins.repr(explicitArg));
                        }
                        else
                        {
                            int start = startIndex + 1;
                            int argCount = MatchArgument(action, argStringsPattern.Substring(start));
                            stop = start + argCount;
                            actionTuples.Add((action, argStrings.GetRange(start, argCount), optionString));
                            break;
                        }
                    }
                    foreach (var (act, args, opt) in actionTuples)
                    {
                        if (act.deprecated && warned.Add(opt)) Warning($"option '{opt}' is deprecated");
                        TakeAction(act, args, opt);
                    }
                    return stop;
                }

                var positionals = _actions.Where(a => a.option_strings.Count == 0).ToList();

                int ConsumePositionals(int startIndex, string pat, List<string> strings)
                {
                    var argCounts = MatchArgumentsPartial(positionals, pat.Substring(startIndex));
                    for (int k = 0; k < argCounts.Count; k++)
                    {
                        var action = positionals[k];
                        int argCount = argCounts[k];
                        var args = strings.GetRange(startIndex, argCount);
                        if (NargsIs(action.nargs, PARSER))
                        {
                            if (pat[startIndex] == '-') args.Remove("--");
                        }
                        else if (!NargsIs(action.nargs, REMAINDER))
                        {
                            if (pat.IndexOf('-', startIndex, argCount) >= 0) args.Remove("--");
                        }
                        startIndex += argCount;
                        if (args.Count > 0 && action.deprecated && warned.Add(action.dest)) Warning($"argument '{action.dest}' is deprecated");
                        TakeAction(action, args);
                    }
                    positionals.RemoveRange(0, argCounts.Count);
                    return startIndex;
                }

                int startIdx = 0;
                int maxOptionStringIndex = optionStringIndices.Count > 0 ? optionStringIndices.Keys.Max() : -1;
                while (startIdx <= maxOptionStringIndex)
                {
                    int nextOptionStringIndex = startIdx;
                    while (nextOptionStringIndex <= maxOptionStringIndex && !optionStringIndices.ContainsKey(nextOptionStringIndex)) nextOptionStringIndex++;
                    if (!intermixed && startIdx != nextOptionStringIndex)
                    {
                        int positionalsEndIndex = ConsumePositionals(startIdx, argStringsPattern, argStrings);
                        if (positionalsEndIndex > startIdx) { startIdx = positionalsEndIndex; continue; }
                        startIdx = positionalsEndIndex;
                    }
                    if (!optionStringIndices.ContainsKey(startIdx))
                    {
                        extras.AddRange(argStrings.GetRange(startIdx, nextOptionStringIndex - startIdx));
                        extrasPattern.AddRange(argStringsPattern.Substring(startIdx, nextOptionStringIndex - startIdx));
                        startIdx = nextOptionStringIndex;
                    }
                    startIdx = ConsumeOptional(startIdx);
                }

                if (!intermixed)
                {
                    int stopIndex = ConsumePositionals(startIdx, argStringsPattern, argStrings);
                    extras.AddRange(argStrings.Skip(stopIndex));
                }
                else
                {
                    extras.AddRange(argStrings.Skip(startIdx));
                    extrasPattern.AddRange(argStringsPattern.Substring(startIdx));
                    string ep = new string(extrasPattern.ToArray());
                    var strings = extras.Where((s, i) => ep[i] != 'O').ToList();
                    string pat = ep.Replace("O", "");
                    int stopIndex = ConsumePositionals(0, pat, strings);
                    var kept = new List<string>();
                    for (int i = 0; i < extras.Count; i++)
                    {
                        if (stopIndex > 0 && ep[i] != 'O') { stopIndex--; continue; }
                        kept.Add(extras[i]);
                    }
                    extras = kept;
                }

                // required actions that did not appear; string defaults converted by type
                var requiredActions = new List<string>();
                foreach (var action in _actions)
                {
                    if (seenActions.Contains(action)) continue;
                    if (action.required) requiredActions.Add(NameOf(action) ?? "");
                    else if (action.@default is string sd && ns.Has(action.dest) && ReferenceEquals(sd, ns.Get(action.dest)))
                        ns.Set(action.dest, GetValue(action, sd));
                }
                if (requiredActions.Count > 0)
                    throw new ArgumentError(null, "the following arguments are required: " + string.Join(", ", requiredActions));

                foreach (var g in _mutually_exclusive_groups)
                {
                    if (!g.required || g._group_actions.Any(seenNonDefaultActions.Contains)) continue;
                    var names = g._group_actions.Where(a => !IsSuppress(a.help)).Select(a => NameOf(a));
                    throw new ArgumentError(null, "one of the arguments " + string.Join(" ", names) + " is required");
                }
                return (ns, extras);
            }

            List<string> ReadArgsFromFiles(List<string> argStrings)
            {
                var result = new List<string>();
                foreach (var s in argStrings)
                {
                    if (s.Length == 0 || fromfile_prefix_chars!.IndexOf(s[0]) < 0) { result.Add(s); continue; }
                    try
                    {
                        var lines = System.IO.File.ReadAllText(s.Substring(1)).Split('\n');
                        var fileArgs = new List<string>();
                        for (int i = 0; i < lines.Length; i++)
                        {
                            if (i == lines.Length - 1 && lines[i].Length == 0) break;
                            fileArgs.Add(lines[i].TrimEnd('\r'));
                        }
                        result.AddRange(ReadArgsFromFiles(fileArgs));
                    }
                    catch (System.IO.FileNotFoundException) { throw new ArgumentError(null, $"[Errno 2] No such file or directory: {Builtins.repr(s.Substring(1))}"); }
                    catch (System.IO.DirectoryNotFoundException) { throw new ArgumentError(null, $"[Errno 2] No such file or directory: {Builtins.repr(s.Substring(1))}"); }
                    catch (System.IO.IOException e) { throw new ArgumentError(null, e.Message); }
                    catch (UnauthorizedAccessException) { throw new ArgumentError(null, $"[Errno 13] Permission denied: {Builtins.repr(s.Substring(1))}"); }
                }
                return result;
            }

            /// <summary>The number of argument strings the action takes from the start of the pattern.</summary>
            int MatchArgument(Action action, string argStringsPattern)
            {
                var m = Regex.Match(argStringsPattern, "\\A" + NargsPattern(action));
                if (!m.Success)
                {
                    string msg = action.nargs switch
                    {
                        null => "expected one argument",
                        string s when s == OPTIONAL => "expected at most one argument",
                        string s when s == ONE_OR_MORE => "expected at least one argument",
                        long n => n == 1 ? $"expected {n} argument" : $"expected {n} arguments",
                        var o => $"expected {Builtins.str(o)} arguments",
                    };
                    throw new ArgumentError(action, msg);
                }
                return m.Groups[1].Length;
            }

            List<int> MatchArgumentsPartial(List<Action> actions, string argStringsPattern)
            {
                for (int i = actions.Count; i > 0; i--)
                {
                    string pattern = string.Concat(actions.Take(i).Select(NargsPattern));
                    var m = Regex.Match(argStringsPattern, "\\A" + pattern);
                    if (!m.Success) continue;
                    var result = new List<int>();
                    for (int g = 1; g < m.Groups.Count; g++) result.Add(m.Groups[g].Length);
                    int end = m.Index + m.Length;
                    if (end < argStringsPattern.Length && argStringsPattern[end] == 'O')
                        while (result.Count > 0 && result[^1] == 0) result.RemoveAt(result.Count - 1);
                    return result;
                }
                return new List<int>();
            }

            List<OptionTuple>? ParseOptional(string argString)
            {
                if (argString.Length == 0) return null;
                if (prefix_chars.IndexOf(argString[0]) < 0) return null;
                if (_option_string_actions.TryGetValue(argString, out var exact)) return new List<OptionTuple> { new OptionTuple(exact, argString, null, null) };
                if (argString.Length == 1) return null;
                int eq = argString.IndexOf('=');
                if (eq >= 0 && _option_string_actions.TryGetValue(argString.Substring(0, eq), out var withArg))
                    return new List<OptionTuple> { new OptionTuple(withArg, argString.Substring(0, eq), "=", argString.Substring(eq + 1)) };
                var optionTuples = GetOptionTuples(argString);
                if (optionTuples.Count > 0) return optionTuples;
                if (NegativeNumber.IsMatch(argString) && !_has_negative_number_optionals) return null;
                if (argString.Contains(' ')) return null;
                return new List<OptionTuple> { new OptionTuple(null, argString, null, null) };
            }

            List<OptionTuple> GetOptionTuples(string optionString)
            {
                var result = new List<OptionTuple>();
                string chars = prefix_chars;
                if (chars.IndexOf(optionString[0]) >= 0 && chars.IndexOf(optionString[1]) >= 0)
                {
                    if (allow_abbrev)
                    {
                        int eq = optionString.IndexOf('=');
                        string prefix = eq >= 0 ? optionString.Substring(0, eq) : optionString;
                        string? sep = eq >= 0 ? "=" : null, explicitArg = eq >= 0 ? optionString.Substring(eq + 1) : null;
                        foreach (var kv in _option_string_actions)
                            if (kv.Key.StartsWith(prefix, StringComparison.Ordinal)) result.Add(new OptionTuple(kv.Value, kv.Key, sep, explicitArg));
                    }
                }
                else if (chars.IndexOf(optionString[0]) >= 0 && chars.IndexOf(optionString[1]) < 0)
                {
                    int eq = optionString.IndexOf('=');
                    string prefix = eq >= 0 ? optionString.Substring(0, eq) : optionString;
                    string? sep = eq >= 0 ? "=" : null, explicitArg = eq >= 0 ? optionString.Substring(eq + 1) : null;
                    string shortPrefix = optionString.Substring(0, 2), shortExplicitArg = optionString.Substring(2);
                    foreach (var kv in _option_string_actions)
                    {
                        if (kv.Key == shortPrefix) result.Add(new OptionTuple(kv.Value, kv.Key, "", shortExplicitArg));
                        else if (allow_abbrev && kv.Key.StartsWith(prefix, StringComparison.Ordinal)) result.Add(new OptionTuple(kv.Value, kv.Key, sep, explicitArg));
                    }
                }
                else throw new ArgumentError(null, "unexpected option string: " + optionString);
                return result;
            }

            static string NargsPattern(Action action)
            {
                bool option = action.option_strings.Count > 0;
                string p = action.nargs switch
                {
                    null => option ? "([A])" : "(-*A-*)",
                    string s when s == OPTIONAL => option ? "(A?)" : "(-*A?-*)",
                    string s when s == ZERO_OR_MORE => option ? "(A*)" : "(-*[A-]*)",
                    string s when s == ONE_OR_MORE => option ? "(A+)" : "(-*A[A-]*)",
                    string s when s == REMAINDER => option ? "([AO]*)" : "(.*)",
                    string s when s == PARSER => option ? "(A[AO]*)" : "(-*A[-AO]*)",
                    string s when s == SUPPRESS => option ? "()" : "(-*)",
                    long n => option ? $"([AO]{{{n}}})" : $"((?:-*A){{{n}}}-*)",
                    var o => throw new ArgumentException("invalid nargs value"),
                };
                return p;
            }

            object? GetValues(Action action, List<string> argStrings)
            {
                object? value;
                if (argStrings.Count == 0 && NargsIs(action.nargs, OPTIONAL))
                {
                    value = action.option_strings.Count > 0 ? action.@const : action.@default;
                    if (value is string s && !IsSuppress(s)) value = GetValue(action, s);
                }
                else if (argStrings.Count == 0 && NargsIs(action.nargs, ZERO_OR_MORE) && action.option_strings.Count == 0)
                    value = action.@default ?? TypedList(new List<object?>(), action);
                else if (argStrings.Count == 1 && (action.nargs == null || NargsIs(action.nargs, OPTIONAL)))
                {
                    value = GetValue(action, argStrings[0]);
                    CheckValue(action, value);
                }
                else if (NargsIs(action.nargs, REMAINDER))
                    value = TypedList(argStrings.Select(v => GetValue(action, v)).ToList(), action);
                else if (NargsIs(action.nargs, PARSER))
                {
                    var list = argStrings.Select(v => GetValue(action, v)).ToList();
                    CheckValue(action, list[0]);
                    value = list;
                }
                else if (IsSuppress(action.nargs)) value = SUPPRESS;
                else
                {
                    var list = argStrings.Select(v => GetValue(action, v)).ToList();
                    foreach (var v in list) CheckValue(action, v);
                    value = TypedList(list, action);
                }
                return value;
            }

            object? GetValue(Action action, string argString)
            {
                if (action.type == null) return argString;
                try { return Norm(action.type(argString)); }
                catch (ArgumentTypeError err) { throw new ArgumentError(action, err.Message); }
                catch (Exception e) when (e is ArgumentException || e is FormatException || e is InvalidCastException || e is OverflowException ||
                                          e is Microsoft.CSharp.RuntimeBinder.RuntimeBinderException)
                {
                    string name = action.TypeName ?? action.TypeRepr();
                    throw new ArgumentError(action, $"invalid {name} value: {Builtins.repr(argString)}");
                }
            }

            void CheckValue(Action action, object? value)
            {
                if (action.choices == null && action.NameParserMap == null) return;
                var choices = action.ChoiceValues().ToList();
                if (choices.Any(c => Builtins.eq(c, value))) return;
                string msg = $"invalid choice: {Builtins.repr(Builtins.str(value))} (choose from {string.Join(", ", choices.Select(Builtins.str))})";
                if (suggest_on_error && value is string sv && choices.All(c => c is string))
                {
                    var close = CloseMatch(sv, choices.Cast<string>().ToList());
                    if (close != null) msg = $"invalid choice: {Builtins.repr(sv)}, maybe you meant {Builtins.repr(close)}? (choose from {string.Join(", ", choices.Select(Builtins.str))})";
                }
                throw new ArgumentError(action, msg);
            }

            /// <summary>difflib.get_close_matches(word, possibilities, 1): the most similar choice with a ratio of at least 0.6.</summary>
            static string? CloseMatch(string word, List<string> possibilities)
            {
                // the highest ratio wins; equal ratios go to the larger string, as heapq.nlargest orders (score, word) pairs
                string? best = null; double bestScore = 0;
                foreach (var p in possibilities)
                {
                    double r = Ratio(word, p);
                    if (r >= 0.6 && (best == null || r > bestScore || r == bestScore && string.CompareOrdinal(p, best) > 0)) { best = p; bestScore = r; }
                }
                return best;

                static double Ratio(string a, string b)
                {
                    if (a.Length + b.Length == 0) return 1.0;
                    return 2.0 * Matches(a, b) / (a.Length + b.Length);
                }
                static int Matches(string a, string b)
                {
                    // SequenceMatcher: the longest matching block, then recursively the parts on either side
                    if (a.Length == 0 || b.Length == 0) return 0;
                    int bestI = 0, bestJ = 0, bestK = 0;
                    for (int i = 0; i < a.Length; i++)
                        for (int j = 0; j < b.Length; j++)
                        {
                            int k = 0;
                            while (i + k < a.Length && j + k < b.Length && a[i + k] == b[j + k]) k++;
                            if (k > bestK) { bestI = i; bestJ = j; bestK = k; }
                        }
                    if (bestK == 0) return 0;
                    return bestK + Matches(a.Substring(0, bestI), b.Substring(0, bestJ)) + Matches(a.Substring(bestI + bestK), b.Substring(bestJ + bestK));
                }
            }

            /// <summary>A list of parsed values as a list of their type (List&lt;long&gt; for type=int), so typed Python code can take it.</summary>
            static object TypedList(List<object?> items, Action action)
            {
                if (items.Count == 0) return action.type == null ? new List<string>() : items;
                var t = items[0]?.GetType();
                if (t == null || items.Any(i => i == null || i.GetType() != t)) return items;
                if (t == typeof(string)) return items.Cast<string>().ToList();
                if (t == typeof(long)) return items.Cast<long>().ToList();
                if (t == typeof(double)) return items.Cast<double>().ToList();
                if (t == typeof(bool)) return items.Cast<bool>().ToList();
                try
                {
                    var list = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(t))!;
                    foreach (var i in items) list.Add(i);
                    return list;
                }
                catch (Exception) { return items; }
            }

            static List<object?> CopyItems(object? items) => items switch
            {
                null => new List<object?>(),
                string s => new List<object?> { s },
                IEnumerable e => e.Cast<object?>().ToList(),
                _ => new List<object?> { items },
            };

            void Invoke(Action action, Namespace ns, object? values, string? optionString)
            {
                switch (action.Kind)
                {
                    case "store": ns.Set(action.dest, values); break;
                    case "store_const": case "store_true": case "store_false": ns.Set(action.dest, action.@const); break;
                    case "append":
                    {
                        var items = CopyItems(ns.Get(action.dest));
                        items.Add(values);
                        ns.Set(action.dest, TypedList(items, action));
                        break;
                    }
                    case "append_const":
                    {
                        var items = CopyItems(ns.Get(action.dest));
                        items.Add(action.@const);
                        ns.Set(action.dest, TypedList(items, action));
                        break;
                    }
                    case "extend":
                    {
                        var items = CopyItems(ns.Get(action.dest));
                        items.AddRange(CopyItems(values));
                        ns.Set(action.dest, TypedList(items, action));
                        break;
                    }
                    case "count":
                    {
                        object? count = ns.Get(action.dest) ?? 0L;
                        ns.Set(action.dest, count is long c ? c + 1 : (object?)((dynamic)count + 1L));
                        break;
                    }
                    case "help": print_help(); exit(); break;
                    case "version":
                    {
                        var formatter = GetFormatter();
                        formatter.add_text(action.version);
                        PrintMessage(formatter.format_help(), sys_.stdout);
                        exit();
                        break;
                    }
                    case "boolean_optional":
                        if (optionString != null && action.option_strings.Contains(optionString)) ns.Set(action.dest, !optionString.StartsWith("--no-"));
                        break;
                    case "parsers":
                    {
                        var list = (List<object?>)values!;
                        string parserName = (string)list[0]!;
                        var argStrings = list.Skip(1).Select(v => (string)v!).ToList();
                        if (action.dest != SUPPRESS) ns.Set(action.dest, parserName);
                        if (!action.NameParserMap!.TryGetValue(parserName, out var subparser))
                            throw new ArgumentError(action, $"unknown parser {Builtins.repr(parserName)} (choices: {string.Join(", ", action.NameParserMap.Keys)})");
                        if (action.DeprecatedNames.Contains(parserName)) Warning($"command '{parserName}' is deprecated");
                        var (subNs, rest) = subparser.ParseKnownArgs(argStrings, null, false);
                        foreach (var kv in subNs.Items()) ns.Set(kv.Key, kv.Value);
                        if (rest.Count > 0)
                        {
                            if (!ns.Has(UnrecognizedArgsAttr)) ns.Set(UnrecognizedArgsAttr, new List<string>());
                            ((List<string>)ns.Get(UnrecognizedArgsAttr)!).AddRange(rest);
                        }
                        break;
                    }
                }
            }

            // ── help ──

            public string format_usage()
            {
                var formatter = GetFormatter();
                formatter.add_usage(usage, _actions, _mutually_exclusive_groups);
                return formatter.format_help();
            }

            public string format_help()
            {
                var formatter = GetFormatter();
                formatter.add_usage(usage, _actions, _mutually_exclusive_groups);
                formatter.add_text(description);
                foreach (var g in _action_groups)
                {
                    formatter.start_section(g.title);
                    formatter.add_text(g.description);
                    formatter.add_arguments(g._group_actions);
                    formatter.end_section();
                }
                formatter.add_text(epilog);
                return formatter.format_help();
            }

            public void print_usage(object? file = null) => PrintMessage(format_usage(), file ?? sys_.stdout);
            public void print_help(object? file = null) => PrintMessage(format_help(), file ?? sys_.stdout);

            static void PrintMessage(string message, object? file)
            {
                if (string.IsNullOrEmpty(message)) return;
                PyConsole.Write(file ?? sys_.stderr, message);
            }

            public void exit(long status = 0, string? message = null)
            {
                if (!string.IsNullOrEmpty(message)) PrintMessage(message, sys_.stderr);
                PyConsole.Exit(checked((int)status));
            }

            public void error(string message)
            {
                print_usage(sys_.stderr);
                exit(2, $"{prog}: error: {message}\n");
            }

            void Warning(string message) => PrintMessage($"{prog}: warning: {message}\n", sys_.stderr);
        }

        // ── HelpFormatter ──

        /// <summary>The colors of argparse's theme (_colorize.Argparse), or none.</summary>
        internal sealed class Theme
        {
            public string usage = "", prog = "", prog_extra = "", heading = "", summary_long_option = "", summary_short_option = "",
                          summary_label = "", summary_action = "", long_option = "", short_option = "", label = "", action = "", reset = "";
            public static readonly Theme Plain = new Theme();
            public static readonly Theme Color = new Theme
            {
                usage = "\x1b[1;34m", prog = "\x1b[1;35m", prog_extra = "\x1b[35m", heading = "\x1b[1;34m", summary_long_option = "\x1b[36m",
                summary_short_option = "\x1b[32m", summary_label = "\x1b[33m", summary_action = "\x1b[32m", long_option = "\x1b[1;36m",
                short_option = "\x1b[1;32m", label = "\x1b[1;33m", action = "\x1b[1;32m", reset = "\x1b[0m",
            };
        }

        /// <summary>HelpFormatter (and its Raw*, ArgumentDefaults and MetavarType variants), as in CPython.</summary>
        internal sealed class _Formatter
        {
            readonly string _prog;
            readonly int _kind; // 0 HelpFormatter, 1 RawDescription, 2 RawText, 3 ArgumentDefaults, 4 MetavarType
            readonly int _indent_increment = 2, _max_help_position, _width;
            int _current_indent, _level, _action_max_length;
            readonly Section _root_section;
            Section _current_section;
            readonly Theme t;
            static readonly Regex WhitespaceMatcher = new Regex(@"[ \t\n\r\f\v]+", RegexOptions.CultureInvariant);
            static readonly Regex LongBreakMatcher = new Regex(@"\n\n\n+", RegexOptions.CultureInvariant);
            static readonly Regex HelpKeys = new Regex(@"%\(([^)]*)\)", RegexOptions.CultureInvariant);

            sealed class Section
            {
                readonly _Formatter f; public readonly Section? parent; readonly string? heading;
                public readonly List<Func<string>> items = new List<Func<string>>();
                public Section(_Formatter f, Section? parent, string? heading = null) { this.f = f; this.parent = parent; this.heading = heading; }
                public string format_help()
                {
                    if (parent != null) f._indent();
                    string itemHelp = f._join_parts(items.Select(i => i()));
                    if (parent != null) f._dedent();
                    if (itemHelp.Length == 0) return "";
                    string h = heading != null && heading != SUPPRESS ? new string(' ', f._current_indent) + f.t.heading + heading + ":" + f.t.reset + "\n" : "";
                    return f._join_parts(new[] { "\n", h, itemHelp, "\n" });
                }
            }

            public _Formatter(string prog, int kind, bool color, int indentIncrement = 2, int maxHelpPosition = 24, int? width = null)
            {
                _prog = prog;
                _kind = kind;
                t = color ? Theme.Color : Theme.Plain;
                int w = width ?? PyConsole.TerminalColumns() - 2;
                _indent_increment = indentIncrement;
                _max_help_position = Math.Min(maxHelpPosition, Math.Max(w - 20, indentIncrement * 2));
                _width = w;
                _root_section = new Section(this, null);
                _current_section = _root_section;
            }

            string Decolor(string s) => ReferenceEquals(t, Theme.Plain) ? s : PyConsole.Decolor(s);

            void _indent() { _current_indent += _indent_increment; _level++; }
            void _dedent() { _current_indent -= _indent_increment; _level--; }
            void _add_item(Func<string> func) => _current_section.items.Add(func);

            public void start_section(string? heading)
            {
                _indent();
                var section = new Section(this, _current_section, heading);
                _add_item(section.format_help);
                _current_section = section;
            }

            public void end_section() { _current_section = _current_section.parent!; _dedent(); }

            public void add_text(string? text) { if (text != null && text != SUPPRESS) _add_item(() => _format_text(text)); }

            public void add_usage(string? usage, List<Action> actions, List<_MutuallyExclusiveGroup> groups, string? prefix = null)
            {
                if (usage != SUPPRESS) _add_item(() => _format_usage(usage, actions, groups, prefix));
            }

            public void add_argument(Action action)
            {
                if (action.help == SUPPRESS) return;
                int length = Decolor(_format_action_invocation(action)).Length + _current_indent;
                foreach (var sub in IndentedSubactions(action)) length = Math.Max(length, Decolor(_format_action_invocation(sub)).Length + _current_indent);
                _action_max_length = Math.Max(_action_max_length, length);
                _add_item(() => _format_action(action));
            }

            public void add_arguments(IEnumerable<Action> actions) { foreach (var a in actions) add_argument(a); }

            public string format_help()
            {
                string help = _root_section.format_help();
                if (help.Length > 0)
                {
                    help = LongBreakMatcher.Replace(help, "\n\n");
                    help = help.Trim('\n') + "\n";
                }
                return help;
            }

            string _join_parts(IEnumerable<string> parts) => string.Concat(parts.Where(p => !string.IsNullOrEmpty(p) && p != SUPPRESS));

            string _format_usage(string? usage, List<Action> actions, List<_MutuallyExclusiveGroup> groups, string? prefix)
            {
                prefix ??= "usage: ";
                if (usage != null)
                    usage = t.prog_extra + Builtins.__percent(usage, new Dictionary<string, object?> { ["prog"] = t.prog + _prog + t.reset + t.prog_extra }) + t.reset;
                else if (actions.Count == 0)
                    usage = t.prog + _prog + t.reset;
                else
                {
                    string prog = _prog;
                    var (parts, posStart) = _get_actions_usage_parts(actions, groups);
                    usage = string.Join(" ", new[] { prog }.Concat(parts).Where(p => !string.IsNullOrEmpty(p)));
                    int textWidth = _width - _current_indent;
                    if (prefix.Length + Decolor(usage).Length > textWidth)
                    {
                        var optParts = parts.Take(posStart).ToList();
                        var posParts = parts.Skip(posStart).ToList();
                        List<string> GetLines(List<string> ps, string indent, string? pre = null)
                        {
                            var lines = new List<string>();
                            var line = new List<string>();
                            int indentLength = indent.Length;
                            int lineLen = pre != null ? pre.Length - 1 : indentLength - 1;
                            foreach (var part in ps)
                            {
                                int partLen = Decolor(part).Length;
                                if (lineLen + 1 + partLen > textWidth && line.Count > 0)
                                {
                                    lines.Add(indent + string.Join(" ", line));
                                    line.Clear();
                                    lineLen = indentLength - 1;
                                }
                                line.Add(part);
                                lineLen += partLen + 1;
                            }
                            if (line.Count > 0) lines.Add(indent + string.Join(" ", line));
                            if (pre != null) lines[0] = lines[0].Substring(indentLength);
                            return lines;
                        }
                        List<string> wrapped;
                        int progLen = Decolor(prog).Length;
                        if (prefix.Length + progLen <= 0.75 * textWidth)
                        {
                            string indent = new string(' ', prefix.Length + progLen + 1);
                            if (optParts.Count > 0)
                            {
                                wrapped = GetLines(new List<string> { prog }.Concat(optParts).ToList(), indent, prefix);
                                wrapped.AddRange(GetLines(posParts, indent));
                            }
                            else if (posParts.Count > 0) wrapped = GetLines(new List<string> { prog }.Concat(posParts).ToList(), indent, prefix);
                            else wrapped = new List<string> { prog };
                        }
                        else
                        {
                            string indent = new string(' ', prefix.Length);
                            var all = optParts.Concat(posParts).ToList();
                            wrapped = GetLines(all, indent);
                            if (wrapped.Count > 1)
                            {
                                wrapped = new List<string>();
                                wrapped.AddRange(GetLines(optParts, indent));
                                wrapped.AddRange(GetLines(posParts, indent));
                            }
                            wrapped.Insert(0, prog);
                        }
                        usage = string.Join("\n", wrapped);
                    }
                    if (usage.StartsWith(prog, StringComparison.Ordinal)) usage = usage.Substring(prog.Length);
                    usage = t.prog + prog + t.reset + usage;
                }
                return t.usage + prefix + t.reset + usage + "\n\n";
            }

            (List<string>, int) _get_actions_usage_parts(List<Action> allActions, List<_MutuallyExclusiveGroup> groups)
            {
                var actions = allActions.Where(a => a.help != SUPPRESS).ToList();
                var actionGroups = new Dictionary<Action, _MutuallyExclusiveGroup?>();
                foreach (var a in actions) actionGroups[a] = null;
                foreach (var g in groups)
                    foreach (var a in g._group_actions)
                        if (actionGroups.ContainsKey(a)) actionGroups[a] = g;
                bool Pop(Action a, out _MutuallyExclusiveGroup? g)
                {
                    if (actionGroups.TryGetValue(a, out g)) { actionGroups.Remove(a); return true; }
                    return false;
                }

                var positionals = new List<(bool? required, List<Action> group)>();
                foreach (var a in actions)
                {
                    if (a.option_strings.Count > 0) continue;
                    Pop(a, out var g);
                    if (g != null)
                    {
                        var ga = g._group_actions.Where(a2 => a2.option_strings.Count > 0 && Pop(a2, out var g2) && g2 != null).ToList();
                        ga.Add(a);
                        positionals.Add((g.required, ga));
                    }
                    else positionals.Add((null, new List<Action> { a }));
                }
                var optionals = new List<(bool? required, List<Action> group)>();
                foreach (var a in actions)
                {
                    if (a.option_strings.Count == 0 || !actionGroups.ContainsKey(a)) continue;
                    Pop(a, out var g);
                    if (g != null)
                    {
                        var ga = new List<Action> { a };
                        ga.AddRange(g._group_actions.Where(a2 => a2.option_strings.Count > 0 && Pop(a2, out var g2) && g2 != null));
                        optionals.Add((g.required, ga));
                    }
                    else optionals.Add((null, new List<Action> { a }));
                }

                var parts = new List<string>();
                int? posStart = null;
                var all = optionals.Concat(positionals).ToList();
                for (int gi = 0; gi < all.Count; gi++)
                {
                    var (required, group) = all[gi];
                    int start = parts.Count;
                    if (gi == optionals.Count) posStart = start;
                    bool inGroup = group.Count > 1;
                    foreach (var action in group)
                    {
                        string part;
                        if (action.option_strings.Count == 0)
                        {
                            part = _format_args(action, DefaultMetavarForPositional(action));
                            if (inGroup && part.Length > 1 && part[0] == '[' && part[^1] == ']') part = part.Substring(1, part.Length - 2);
                            part = t.summary_action + part + t.reset;
                        }
                        else
                        {
                            string optionString = action.option_strings[0];
                            string optionColor = optionString.Length > 2 ? t.summary_long_option : t.summary_short_option;
                            if (action.nargs is long n0 && n0 == 0) part = optionColor + action.format_usage() + t.reset;
                            else part = optionColor + optionString + " " + t.summary_label + _format_args(action, DefaultMetavarForOptional(action)) + t.reset;
                            if (!(action.required || required == true || inGroup)) part = "[" + part + "]";
                        }
                        parts.Add(part);
                    }
                    if (inGroup)
                    {
                        parts[start] = (required == true ? "(" : "[") + parts[start];
                        for (int i = start; i < parts.Count - 1; i++) parts[i] += " |";
                        parts[^1] += required == true ? ")" : "]";
                    }
                }
                return (parts, posStart ?? parts.Count);
            }

            string _format_text(string text)
            {
                if (text.Contains("%(prog)")) text = Builtins.__percent(text, new Dictionary<string, object?> { ["prog"] = _prog });
                int textWidth = Math.Max(_width - _current_indent, 11);
                string indent = new string(' ', _current_indent);
                return _fill_text(text, textWidth, indent) + "\n\n";
            }

            string _format_action(Action action)
            {
                int helpPosition = Math.Min(_action_max_length + 2, _max_help_position);
                int helpWidth = Math.Max(_width - helpPosition, 11);
                int actionWidth = helpPosition - _current_indent - 2;
                string actionHeader = _format_action_invocation(action);
                string actionHeaderNoColor = Decolor(actionHeader);
                int indentFirst = 0;
                if (string.IsNullOrEmpty(action.help))
                    actionHeader = new string(' ', _current_indent) + actionHeader + "\n";
                else if (actionHeaderNoColor.Length <= actionWidth)
                {
                    string colored = actionHeader;
                    actionHeader = new string(' ', _current_indent) + actionHeaderNoColor.PadRight(actionWidth) + "  ";
                    if (!ReferenceEquals(colored, actionHeaderNoColor) && actionHeaderNoColor.Length > 0) actionHeader = actionHeader.Replace(actionHeaderNoColor, colored);
                    indentFirst = 0;
                }
                else
                {
                    actionHeader = new string(' ', _current_indent) + actionHeader + "\n";
                    indentFirst = helpPosition;
                }
                var parts = new List<string> { actionHeader };
                if (!string.IsNullOrEmpty(action.help) && action.help.Trim().Length > 0)
                {
                    string helpText = _expand_help(action);
                    if (helpText.Length > 0)
                    {
                        var helpLines = _split_lines(helpText, helpWidth);
                        if (helpLines.Count > 0)
                        {
                            parts.Add(new string(' ', indentFirst) + helpLines[0] + "\n");
                            foreach (var line in helpLines.Skip(1)) parts.Add(new string(' ', helpPosition) + line + "\n");
                        }
                    }
                }
                else if (!actionHeader.EndsWith("\n")) parts.Add("\n");
                foreach (var sub in IndentedSubactions(action)) parts.Add(_format_action(sub));
                return _join_parts(parts);
            }

            /// <summary>_iter_indented_subactions: the subcommands of a subparsers action, one level deeper.</summary>
            IEnumerable<Action> IndentedSubactions(Action action)
            {
                if (action.Kind != "parsers") yield break;
                _indent();
                foreach (var sub in action.ChoicesActions) yield return sub;
                _dedent();
            }

            string _format_action_invocation(Action action)
            {
                if (action.option_strings.Count == 0)
                    return t.action + string.Join(" ", _metavar_formatter(action, DefaultMetavarForPositional(action))(1)) + t.reset;
                var colored = action.option_strings.Select(s => (s.Length > 2 ? t.long_option : t.short_option) + s + t.reset);
                if (action.nargs is long n && n == 0) return string.Join(", ", colored);
                return string.Join(", ", colored) + " " + t.label + _format_args(action, DefaultMetavarForOptional(action)) + t.reset;
            }

            Func<int, string[]> _metavar_formatter(Action action, string? defaultMetavar)
            {
                object? result;
                if (action.metavar != null) result = action.metavar;
                else if (action.choices != null || action.NameParserMap != null) result = "{" + string.Join(",", action.ChoiceValues().Select(Builtins.str)) + "}";
                else result = defaultMetavar;
                return size =>
                {
                    if (MetavarTuple(result) is string[] tuple) return tuple;
                    var r = new string[size];
                    for (int i = 0; i < size; i++) r[i] = result == null ? "None" : Builtins.str(result);
                    return r;
                };
            }

            internal string _format_args(Action action, string? defaultMetavar)
            {
                var getMetavar = _metavar_formatter(action, defaultMetavar);
                string[] Need(int n) { var m = getMetavar(n); if (m.Length != n) throw new InvalidCastException("not enough arguments for format string"); return m; }
                switch (action.nargs)
                {
                    case null: return Need(1)[0];
                    case string s when s == OPTIONAL: return "[" + Need(1)[0] + "]";
                    case string s when s == ZERO_OR_MORE:
                    {
                        var m = getMetavar(1);
                        if (m.Length == 2) return $"[{m[0]} [{m[1]} ...]]";
                        if (m.Length != 1) throw new InvalidCastException("not all arguments converted during string formatting");
                        return $"[{m[0]} ...]";
                    }
                    case string s when s == ONE_OR_MORE: { var m = Need(2); return $"{m[0]} [{m[1]} ...]"; }
                    case string s when s == REMAINDER: return "...";
                    case string s when s == PARSER: return Need(1)[0] + " ...";
                    case string s when s == SUPPRESS: return "";
                    case long n: return string.Join(" ", Need((int)n));
                    default: throw new ArgumentException("invalid nargs value");
                }
            }

            internal string _expand_help(Action action)
            {
                string helpString = _get_help_string(action);
                if (!helpString.Contains('%')) return helpString;
                var ps = new Dictionary<string, object?>
                {
                    ["option_strings"] = action.option_strings, ["dest"] = action.dest, ["nargs"] = action.nargs, ["const"] = action.@const,
                    ["default"] = action.@default, ["type"] = action.type == null ? null : action.TypeName ?? action.TypeRepr(),
                    ["choices"] = action.choices, ["required"] = action.required, ["help"] = action.help, ["metavar"] = action.metavar,
                    ["deprecated"] = action.deprecated,
                };
                if (action.Kind == "version") ps["version"] = action.version;
                ps["prog"] = _prog;
                foreach (var k in ps.Keys.ToList()) if (IsSuppress(ps[k])) ps.Remove(k);
                if (ps.TryGetValue("choices", out var ch) && ch != null) ps["choices"] = string.Join(", ", action.ChoiceValues().Select(Builtins.str));
                foreach (Match m in HelpKeys.Matches(helpString))
                    if (!ps.ContainsKey(m.Groups[1].Value)) throw new KeyNotFoundException(Builtins.repr(m.Groups[1].Value));
                return Builtins.__percent(helpString, ps);
            }

            List<string> _split_lines(string text, int width)
            {
                if (_kind == 2) return SplitLines(text, false);
                text = WhitespaceMatcher.Replace(text, " ").Trim();
                return PyTextWrap.Wrap(text, width);
            }

            string _fill_text(string text, int width, string indent)
            {
                if (_kind == 1 || _kind == 2) return string.Concat(SplitLines(text, true).Select(line => indent + line));
                text = WhitespaceMatcher.Replace(text, " ").Trim();
                return PyTextWrap.Fill(text, width, indent, indent);
            }

            /// <summary>str.splitlines(keepends).</summary>
            static List<string> SplitLines(string s, bool keepEnds)
            {
                var lines = new List<string>();
                int start = 0;
                for (int i = 0; i < s.Length; i++)
                {
                    char c = s[i];
                    if (c != '\n' && c != '\r' && c != '\v' && c != '\f' && c != '\x1c' && c != '\x1d' && c != '\x1e' && c != '\x85' && c != '\u2028' && c != '\u2029') continue;
                    int end = i;
                    if (c == '\r' && i + 1 < s.Length && s[i + 1] == '\n') i++;
                    lines.Add(keepEnds ? s.Substring(start, i + 1 - start) : s.Substring(start, end - start));
                    start = i + 1;
                }
                if (start < s.Length) lines.Add(s.Substring(start));
                return lines;
            }

            string _get_help_string(Action action)
            {
                string help = action.help ?? "";
                if (_kind == 3 && !help.Contains("%(default)") && !IsSuppress(action.@default) && !action.required &&
                    (action.option_strings.Count > 0 || NargsIs(action.nargs, OPTIONAL) || NargsIs(action.nargs, ZERO_OR_MORE)))
                    help += " (default: %(default)s)";
                return help;
            }

            string DefaultMetavarForOptional(Action action) => _kind == 4 ? action.TypeName ?? "None" : action.dest.ToUpperInvariant();
            string DefaultMetavarForPositional(Action action) => _kind == 4 ? action.TypeName ?? "None" : action.dest;
        }

        // ── module-level helpers ──

        /// <summary>argparse.FileType(mode): a type= that opens the named file ('-' is stdin / stdout).</summary>
        public static Func<string, object?> FileType(string mode = "r", long bufsize = -1, string? encoding = null, string? errors = null) => s =>
        {
            if (s == "-")
            {
                if (mode.StartsWith("r")) return sys_.stdin;
                if (mode.IndexOfAny(new[] { 'w', 'a', 'x' }) >= 0) return sys_.stdout;
                throw new ArgumentException($"argument \"-\" with mode {mode}");
            }
            try { return new PyFile(s, mode, encoding, errors); }
            catch (Exception e) when (e is System.IO.FileNotFoundException || e is System.IO.DirectoryNotFoundException)
            { throw new ArgumentTypeError($"can't open '{s}': [Errno 2] No such file or directory: {Builtins.repr(s)}"); }
            catch (UnauthorizedAccessException) { throw new ArgumentTypeError($"can't open '{s}': [Errno 13] Permission denied: {Builtins.repr(s)}"); }
            catch (System.IO.IOException e) { throw new ArgumentTypeError($"can't open '{s}': {e.Message}"); }
        };
    }
}
